class Solution {
    public long minimumCost(String s, String t, int flipCost, int swapCost, int crossCost) {
        int n = s.length();
        long a = 0, b = 0; // a: (0,1) mismatches, b: (1,0) mismatches
        for (int i = 0; i < n; i++) {
            char cs = s.charAt(i);
            char ct = t.charAt(i);
            if (cs == '0' && ct == '1') a++;
            else if (cs == '1' && ct == '0') b++;
        }
        long m = Math.min(a, b);      // opposite-type pairs: one swap or two flips
        long r = Math.abs(a - b);     // same-type leftovers
        long cost = m * Math.min(swapCost, 2L * flipCost);
        // two same-type leftovers: cross-swap one then swap, or flip both
        cost += (r / 2) * Math.min(2L * flipCost, (long) crossCost + swapCost);
        // an odd leftover can only be flipped; long arithmetic, totals reach 1e14
        cost += (r % 2) * flipCost;
        return cost;
    }
}

