var minimumCost = function(s, t, flipCost, swapCost, crossCost) {
    let count01 = 0; // s[i] = '0', t[i] = '1'
    let count10 = 0; // s[i] = '1', t[i] = '0'

    for (let i = 0; i < s.length; i++) {
        if (s[i] === '0' && t[i] === '1') {
            count01++;
        } else if (s[i] === '1' && t[i] === '0') {
            count10++;
        }
    }

    const pairs = Math.min(count01, count10);
    const extra = Math.abs(count01 - count10);

    // For a pair of mismatches (one 01 and one 10):
    // Option 1: Flip both at cost 2 * flipCost
    // Option 2: Swap within one string at cost swapCost
    const costPerPair = Math.min(2 * flipCost, swapCost);

    // For two extra mismatches of the same type:
    // Option 1: Flip both at cost 2 * flipCost
    // Option 2: Cross swap one (converting its type) then swap with the other at cost crossCost + swapCost
    const costPerDouble = Math.min(2 * flipCost, crossCost + swapCost);

    // For a single extra mismatch, must flip it
    const costPerSingle = flipCost;

    let total = 0;
    total += pairs * costPerPair;
    total += Math.floor(extra / 2) * costPerDouble;
    total += (extra % 2) * costPerSingle;

    return total;
};

