func minimumCost(s string, t string, flipCost int, swapCost int, crossCost int) int64 {
	fc := int64(flipCost)
	sc := int64(swapCost)
	cc := int64(crossCost)

	// Step 1: count the two kinds of mismatch
	var c01, c10 int
	for i := 0; i < len(s); i++ {
		if s[i] == '0' && t[i] == '1' {
			c01++
		} else if s[i] == '1' && t[i] == '0' {
			c10++
		}
	}

	// Step 2: opposite-type pairs and same-type leftovers
	pairs := c01
	if c10 < pairs {
		pairs = c10
	}
	excess := c01 - c10
	if excess < 0 {
		excess = -excess
	}

	// one swap fixes an opposite pair, or flip both
	costOpposite := sc
	if 2*fc < costOpposite {
		costOpposite = 2 * fc
	}
	total := int64(pairs) * costOpposite

	// Step 3: two same-type leftovers: cross-swap one then swap, or flip both
	costSamePair := 2 * fc
	if cc+sc < costSamePair {
		costSamePair = cc + sc
	}
	total += int64(excess/2) * costSamePair
	// Step 4: an odd leftover can only be flipped
	if excess%2 == 1 {
		total += fc
	}

	return total
}
